<script setup lang="ts">
import { computed, watch } from 'vue'
import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'
import { queryFromState, refine, stateFromQuery, type ListField } from '../investigation'
const route = useRoute(), router = useRouter()
const client = useQueryClient()
const feedId = computed(() => typeof route.query.feed === 'string' ? route.query.feed : undefined)
const selectedId = computed(() => typeof route.query.article === 'string' ? route.query.article : undefined)
const feeds = useInfiniteQuery({ queryKey: ['feeds'], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => api.feeds(pageParam), getNextPageParam: page => page.next_cursor ?? undefined })
const articles = useInfiniteQuery({ queryKey: ['articles', feedId], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => api.articles(feedId.value, pageParam), getNextPageParam: page => page.next_cursor ?? undefined })
const feedItems = computed(() => feeds.data.value?.pages.flatMap(page => page.items) ?? [])
const articleItems = computed(() => articles.data.value?.pages.flatMap(page => page.items) ?? [])
const detail = useQuery({ queryKey: ['article', selectedId], queryFn: () => api.article(selectedId.value!), enabled: () => Boolean(selectedId.value), refetchInterval: 5000 })
const annotations = useQuery({ queryKey: ['article-annotations', selectedId], queryFn: () => api.articleAnnotations(selectedId.value!), enabled: () => Boolean(selectedId.value), refetchInterval: 5000 })
const process = useMutation({ mutationFn: (mode: 'full_text' | 'full_text_html') => api.processArticle(selectedId.value!, mode), onSuccess: () => { client.invalidateQueries({ queryKey: ['article', selectedId] }); client.invalidateQueries({ queryKey: ['jobs'] }) } })
const reprocess = useMutation({ mutationFn: () => api.reprocessArticle(selectedId.value!), onSuccess: () => { client.invalidateQueries({ queryKey: ['article-annotations', selectedId] }); client.invalidateQueries({ queryKey: ['nlp-status'] }) } })
const mentionedCountries = computed(() => annotations.data.value?.countries.filter(item => item.role === 'mentioned') ?? [])
const primaryCountries = computed(() => annotations.data.value?.countries.filter(item => item.role === 'primary') ?? [])
watch(selectedId, () => { process.reset(); reprocess.reset() })
function setQuery(values: Record<string, string | undefined>) { router.replace({ query: { ...route.query, ...values } }) }
function refinedSearch(field: ListField, value: string) {
  const from = typeof route.query.from === 'string' && route.query.from.startsWith('/search') ? route.query.from : ''
  const origin = stateFromQuery(from ? router.resolve(from).query : {})
  return { path: '/search', query: queryFromState(refine(origin, field, value)) }
}
</script>
<template><header><div><p class="eyebrow">RSS archive</p><h2>Articles</h2></div><div><label class="filter">Source<select :value="feedId" @change="setQuery({ feed: ($event.target as HTMLSelectElement).value || undefined, article: undefined })"><option value="">All sources</option><option v-for="feed in feedItems" :key="feed.id" :value="feed.id">{{ feed.name }}</option></select></label><button v-if="feeds.hasNextPage.value" class="secondary" :disabled="feeds.isFetchingNextPage.value" @click="feeds.fetchNextPage()">Load more sources</button></div></header>
  <div class="article-layout"><section class="article-list panel"><p v-if="articles.isPending.value" class="muted">Loading articles…</p><p v-else-if="articles.isError.value" class="error">Could not load articles.</p><p v-else-if="!articleItems.length" class="muted">No collected articles.</p><button v-for="article in articleItems" :key="article.id" class="article-row" @click="setQuery({ article: article.id })"><strong>{{ article.title }}</strong><span>{{ new Date(article.first_discovered_at).toLocaleString() }}</span><small>{{ article.provenance.map(p => p.feed_name).join(', ') }}</small></button><button v-if="articles.hasNextPage.value" class="secondary" :disabled="articles.isFetchingNextPage.value" @click="articles.fetchNextPage()">Load more articles</button></section>
  <section class="panel detail"><p v-if="!selectedId" class="muted">Select an article to inspect its content and feed record.</p><p v-else-if="detail.isPending.value" class="muted">Loading article…</p><p v-else-if="detail.isError.value" class="error">Could not load article details.</p><template v-else-if="detail.data.value"><RouterLink v-if="typeof route.query.from === 'string'" :to="route.query.from">Back to search</RouterLink><p class="eyebrow">Article detail</p><h3>{{ detail.data.value.title }}</h3><a :href="detail.data.value.original_url" target="_blank" rel="noopener noreferrer">Open original article</a><div class="actions processing-actions"><button :disabled="process.isPending.value" @click="process.mutate('full_text')">{{ detail.data.value.content ? 'Refresh text' : 'Fetch text' }}</button><button class="secondary" :disabled="process.isPending.value" @click="process.mutate('full_text_html')">Fetch and retain HTML</button></div><p v-if="process.isPending.value" class="muted">Scheduling processing…</p><p v-if="process.isSuccess.value" class="success">Processing scheduled.</p><p v-if="process.error.value" class="error">Could not schedule processing.</p><article v-if="detail.data.value.content" class="readable"><p class="eyebrow">Readable text</p><p class="muted">Extracted {{ new Date(detail.data.value.content.extracted_at).toLocaleString() }} · {{ detail.data.value.content.change_count }} changes · HTML {{ detail.data.value.content.html_retained ? 'retained' : 'temporary' }}</p><div class="article-text">{{ detail.data.value.content.text }}</div></article><section v-else class="processing"><strong>Content status</strong><p class="muted">{{ detail.data.value.processing[0]?.status || 'Not processed' }}</p><p v-if="detail.data.value.processing[0]?.error_message" class="error">{{ detail.data.value.processing[0].error_category }}: {{ detail.data.value.processing[0].error_message }}</p></section>
    <section class="annotations"><div class="annotation-heading"><h4>Annotations</h4><button class="secondary" :disabled="reprocess.isPending.value" @click="reprocess.mutate()">Reprocess annotations</button></div><p v-if="annotations.isPending.value" class="muted">Loading annotations…</p><p v-else-if="annotations.isError.value" class="error">Could not load annotations.</p><template v-else-if="annotations.data.value"><p v-if="annotations.data.value.language">Detected language: {{ annotations.data.value.language.language }} <span class="muted">({{ Math.round(annotations.data.value.language.confidence * 100) }}% confidence)</span></p><p v-else class="muted">Detected language is not available.</p><p>Source countries: <template v-for="(country, index) in annotations.data.value.source_countries" :key="country">{{ index ? ', ' : '' }}<RouterLink class="annotation-link" :aria-label="`Filter by source country ${country}`" :to="refinedSearch('source_country', country)">{{ country }}</RouterLink></template><template v-if="!annotations.data.value.source_countries.length">None</template></p><p>Mentioned countries: <template v-for="(item, index) in mentionedCountries" :key="item.country_code">{{ index ? ', ' : '' }}<RouterLink class="annotation-link" :aria-label="`Filter by mentioned country ${item.country_code}`" :to="refinedSearch('mentioned_country', item.country_code)">{{ item.country_code }}</RouterLink></template><template v-if="!mentionedCountries.length">None</template></p><p>Primary story country: <template v-for="(item, index) in primaryCountries" :key="item.country_code">{{ index ? ', ' : '' }}<RouterLink class="annotation-link" :aria-label="`Filter by story country ${item.country_code}`" :to="refinedSearch('story_country', item.country_code)">{{ item.country_code }}</RouterLink>{{ item.inferred ? ' (inferred)' : '' }}</template><template v-if="!primaryCountries.length">Not inferred</template></p><div v-if="annotations.data.value.keywords.length" class="annotation-group"><strong>Keywords</strong><RouterLink v-for="keyword in annotations.data.value.keywords" :key="keyword.id" class="annotation-link" :to="refinedSearch('keyword_id', keyword.id)">{{ keyword.text }}</RouterLink></div><div v-if="annotations.data.value.entities.length" class="annotation-group"><strong>Entities</strong><RouterLink v-for="entity in annotations.data.value.entities" :key="entity.id" class="annotation-link" :to="refinedSearch('entity_id', entity.id)">{{ entity.text }} ({{ entity.entity_type }})</RouterLink></div><div class="processor-list"><p v-for="outcome in annotations.data.value.processors" :key="outcome.processor" :class="outcome.status === 'failed' ? 'error' : 'muted'">{{ outcome.processor }} · <template v-if="outcome.completed_generation < outcome.requested_generation">stale · </template>{{ outcome.status }} · generation {{ outcome.completed_generation }}/{{ outcome.requested_generation }} · processor {{ outcome.processor_version }}<span v-if="outcome.model_version"> · model {{ outcome.model_version }}</span><span v-if="outcome.detail"> · {{ outcome.detail }}</span></p><p v-for="capability in annotations.data.value.capabilities.filter(item => item.state !== 'available')" :key="capability.name" class="muted">{{ capability.name }} · {{ capability.state }}<span v-if="capability.detail"> · {{ capability.detail }}</span></p></div></template><p v-if="reprocess.isSuccess.value" class="success">Annotation processing scheduled.</p><p v-if="reprocess.isError.value" class="error">Could not schedule annotation processing.</p></section>
    <section class="story"><h4>Story</h4><template v-if="detail.data.value.story_cluster"><p>{{ detail.data.value.story_cluster.article_count }} articles from {{ detail.data.value.story_cluster.source_count }} sources</p><div v-if="(detail.data.value.related ?? []).length" class="annotation-group"><strong>Related articles</strong><RouterLink v-for="related in detail.data.value.related" :key="related.article_id" class="annotation-link" :to="{ path: route.path, query: { ...route.query, article: related.article_id } }">{{ related.title }}</RouterLink></div><div class="actions"><RouterLink class="secondary" :to="{ path: `/clusters/${detail.data.value.story_cluster.id}`, query: { from: route.fullPath } }">Open full cluster</RouterLink><RouterLink class="annotation-link" aria-label="Filter by story" :to="refinedSearch('story_cluster_id', detail.data.value.story_cluster.id)">Filter by story</RouterLink></div></template><p v-else class="muted">Not part of a detected story.</p></section>
    <dl><dt>Published</dt><dd>{{ detail.data.value.published_at ? new Date(detail.data.value.published_at).toLocaleString() : 'Not supplied' }}</dd><dt>First discovered</dt><dd>{{ new Date(detail.data.value.first_discovered_at).toLocaleString() }}</dd></dl><article v-for="source in detail.data.value.provenance" :key="source.feed_id" class="provenance"><RouterLink class="annotation-link" :aria-label="`Filter by source ${source.feed_name}`" :to="refinedSearch('source_id', source.feed_id)"><strong>{{ source.feed_name }}</strong></RouterLink><p>{{ source.description || 'No RSS description.' }}</p></article></template></section></div>
</template>
